# LOCAL TIME  (Gaborone, UTC+2, no daylight saving)
# Servers such as Streamlit Cloud run in UTC; every record is stamped with
# local wall-clock time, stored naive so it displays the same everywhere.
# ──────────────────────────────────────────────
try:
    from zoneinfo import ZoneInfo
    _APP_TZ = ZoneInfo("Africa/Gaborone")
except Exception:
    _APP_TZ = timezone(timedelta(hours=2))


def now_local():
    return datetime.now(_APP_TZ).replace(tzinfo=None)


def today_local():
    return now_local().date()


