# ──────────────────────────────────────────────
# DATABASE
# ──────────────────────────────────────────────
@st.cache_resource
def get_conn():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.execute("PRAGMA journal_mode=WAL;")
    conn.execute("PRAGMA foreign_keys=ON;")
    return conn


def q(sql, params=()):
    return pd.read_sql_query(sql, get_conn(), params=params)


def init_db():
    c = get_conn()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT);
    CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL,
        category TEXT DEFAULT '',
        brand TEXT DEFAULT '',
        pack_size REAL DEFAULT 0,          -- e.g. 50 (kg in a bag)
        sell_unit TEXT DEFAULT 'bag',      -- what one unit of sale is
        sku TEXT DEFAULT '',
        cost_price REAL DEFAULT 0,         -- weighted-average cost per sell unit
        sell_price REAL DEFAULT 0,         -- selling price per sell unit
        reorder_level REAL DEFAULT 5,      -- alert when stock is at/below this
        loose_of INTEGER,                  -- id of the bag product this loose item is opened from
        active INTEGER DEFAULT 1,
        created_at TEXT);
    CREATE TABLE IF NOT EXISTS suppliers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE NOT NULL, phone TEXT DEFAULT '', email TEXT DEFAULT '',
        address TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT);
    CREATE TABLE IF NOT EXISTS customers (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL, phone TEXT DEFAULT '', village TEXT DEFAULT '',
        credit_limit REAL DEFAULT 0, notes TEXT DEFAULT '', created_at TEXT);
    CREATE TABLE IF NOT EXISTS receipts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id INTEGER NOT NULL, supplier_id INTEGER,
        receive_date TEXT, qty REAL, unit_cost REAL,
        batch TEXT DEFAULT '', expiry_date TEXT DEFAULT '', invoice_ref TEXT DEFAULT '',
        note TEXT DEFAULT '', user TEXT DEFAULT '', logged_at TEXT);
    CREATE TABLE IF NOT EXISTS stock_moves (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        product_id INTEGER NOT NULL,
        move_date TEXT, qty REAL,          -- + into stock, - out of stock
        kind TEXT,                         -- opening/receive/sale/void/adjust/open_bag_out/open_bag_in
        ref_id INTEGER, unit_cost REAL DEFAULT 0,
        note TEXT DEFAULT '', user TEXT DEFAULT '', logged_at TEXT);
    CREATE TABLE IF NOT EXISTS sales (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sale_no TEXT, sale_date TEXT, customer_id INTEGER,
        cashier TEXT DEFAULT '', subtotal REAL DEFAULT 0, discount REAL DEFAULT 0,
        vat REAL DEFAULT 0, total REAL DEFAULT 0, paid REAL DEFAULT 0,
        tendered REAL DEFAULT 0, change_given REAL DEFAULT 0,
        method TEXT DEFAULT 'Cash', status TEXT DEFAULT 'completed',
        note TEXT DEFAULT '', void_reason TEXT DEFAULT '', logged_at TEXT);
    CREATE TABLE IF NOT EXISTS sale_items (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sale_id INTEGER NOT NULL, product_id INTEGER, name TEXT,
        qty REAL, unit_price REAL, discount REAL DEFAULT 0,
        line_total REAL, unit_cost REAL DEFAULT 0);
    CREATE TABLE IF NOT EXISTS payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id INTEGER NOT NULL, pay_date TEXT, amount REAL,
        method TEXT DEFAULT 'Cash', note TEXT DEFAULT '', user TEXT DEFAULT '',
        logged_at TEXT);
    CREATE TABLE IF NOT EXISTS expenses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        exp_date TEXT, category TEXT, description TEXT DEFAULT '', amount REAL,
        method TEXT DEFAULT 'Cash from till', payee TEXT DEFAULT '', note TEXT DEFAULT '',
        user TEXT DEFAULT '', logged_at TEXT);
    CREATE INDEX IF NOT EXISTS ix_exp_date ON expenses(exp_date);
    CREATE INDEX IF NOT EXISTS ix_moves_prod ON stock_moves(product_id);
    CREATE INDEX IF NOT EXISTS ix_items_sale ON sale_items(sale_id);
    CREATE INDEX IF NOT EXISTS ix_sales_date ON sales(sale_date);
    """)
    # Upgrade older databases: each product remembers its usual supplier.
    cols = [r[1] for r in c.execute("PRAGMA table_info(products)").fetchall()]
    if "supplier_id" not in cols:
        c.execute("ALTER TABLE products ADD COLUMN supplier_id INTEGER")
    c.commit()


def get_setting(key, default=""):
    row = get_conn().execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return row[0] if row and row[0] is not None else default


def set_setting(key, value):
    c = get_conn()
    c.execute("INSERT INTO settings(key, value) VALUES(?, ?) "
              "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value)))
    c.commit()


def store_name():
    return get_setting("store_name", "Agri Feed Store")


def currency():
    return get_setting("currency", "P")


def vat_rate():
    try:
        return float(get_setting("vat_rate", "14"))
    except ValueError:
        return 14.0


def vat_mode():
    """'inclusive' — shelf prices already include VAT (VAT is shown, not added);
       'exclusive' — VAT is added on top at the till; 'none' — not VAT registered."""
    return get_setting("vat_mode", "inclusive")


def stamp():
    return now_local().isoformat(timespec="seconds")


def cashier_name():
    return (st.session_state.get("cashier") or "").strip()


# ──────────────────────────────────────────────
# FORMATTING
# ──────────────────────────────────────────────
def fmt(x):
    try:
        x = float(x)
    except (TypeError, ValueError):
        return str(x)
    return f"{int(round(x)):,}" if abs(x - round(x)) < 1e-9 else f"{x:,.2f}"


def money(x, cur=None):
    try:
        x = float(x)
    except (TypeError, ValueError):
        x = 0.0
    cur = currency() if cur is None else cur
    sign = "-" if x < -0.004 else ""
    return f"{sign}{cur} {abs(x):,.2f}"


def r2(x):
    return round(float(x) + 1e-9, 2)


# ──────────────────────────────────────────────
# PRODUCTS & STOCK
# ──────────────────────────────────────────────
def add_product(name, category="", brand="", pack_size=0.0, sell_unit="bag", sku="",
                cost_price=0.0, sell_price=0.0, reorder_level=5.0, opening_qty=0.0,
                loose_of=None, supplier_id=None):
    """Create a product. When a supplier is given, the quantity in stock is booked as a
    purchase from that supplier (so it counts in their “Bought (at cost)”)."""
    c = get_conn()
    cur = c.execute(
        "INSERT INTO products(name, category, brand, pack_size, sell_unit, sku, cost_price, "
        "sell_price, reorder_level, loose_of, active, created_at, supplier_id) "
        "VALUES(?,?,?,?,?,?,?,?,?,?,1,?,?)",
        (name.strip(), category, brand, float(pack_size or 0), sell_unit or "bag", sku,
         float(cost_price or 0), float(sell_price or 0), float(reorder_level or 0),
         loose_of, stamp(), supplier_id))
    pid = cur.lastrowid
    c.commit()
    if opening_qty and float(opening_qty) > 0 and supplier_id:
        receive_stock(pid, opening_qty, cost_price, supplier_id, note="Opening stock")
    elif opening_qty and float(opening_qty) != 0:
        c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, unit_cost, note, "
                  "user, logged_at) VALUES(?,?,?,?,?,?,?,?)",
                  (pid, today_local().isoformat(), float(opening_qty), "opening",
                   float(cost_price or 0), "Opening stock", cashier_name(), stamp()))
    c.commit()
    return pid


def update_product(pid, **fields):
    allowed = {"name", "category", "brand", "pack_size", "sell_unit", "sku", "cost_price",
               "sell_price", "reorder_level", "active", "loose_of", "supplier_id"}
    sets = {k: v for k, v in fields.items() if k in allowed}
    if not sets:
        return
    c = get_conn()
    c.execute("UPDATE products SET " + ", ".join(f"{k}=?" for k in sets) + " WHERE id=?",
              list(sets.values()) + [int(pid)])
    c.commit()


def product_has_history(pid):
    c = get_conn()
    n = c.execute("SELECT COUNT(*) FROM sale_items WHERE product_id=?", (pid,)).fetchone()[0]
    n += c.execute("SELECT COUNT(*) FROM receipts WHERE product_id=?", (pid,)).fetchone()[0]
    return n > 0


def delete_product(pid):
    c = get_conn()
    c.execute("DELETE FROM stock_moves WHERE product_id=?", (pid,))
    c.execute("DELETE FROM products WHERE id=?", (pid,))
    c.commit()


def stock_on_hand(pid):
    v = get_conn().execute("SELECT COALESCE(SUM(qty),0) FROM stock_moves WHERE product_id=?",
                           (int(pid),)).fetchone()[0]
    return float(v or 0)


def get_product(pid):
    df = q("SELECT * FROM products WHERE id=?", (int(pid),))
    return None if df.empty else df.iloc[0]


def price_ex_vat(price):
    """Selling price without VAT (prices are entered as shown on the shelf)."""
    price = float(price or 0)
    return price / (1 + vat_rate() / 100.0) if vat_mode() == "inclusive" else price


def product_status(soh, reorder):
    if soh <= 0:
        return "Out of stock", DANGER
    if soh <= reorder:
        return "Low — reorder", WARN
    return "In stock", OK_GREEN


def status_emoji(level):
    return {"Out of stock": "🟥", "Low — reorder": "🟨", "In stock": "🟩"}.get(level, "⬜")


def stock_table(include_inactive=False):
    """Every product with live stock on hand, stock value and 30-day sales."""
    p = q("SELECT p.*, COALESCE(su.name, '') AS supplier FROM products p "
          "LEFT JOIN suppliers su ON su.id = p.supplier_id"
          + ("" if include_inactive else " WHERE p.active=1") + " ORDER BY p.category, p.name")
    if p.empty:
        return p
    soh = q("SELECT product_id, SUM(qty) AS soh FROM stock_moves GROUP BY product_id")
    since = (today_local() - timedelta(days=29)).isoformat()
    sold = q("SELECT si.product_id, SUM(si.qty) AS sold30, SUM(si.line_total) AS rev30 "
             "FROM sale_items si JOIN sales s ON s.id=si.sale_id "
             "WHERE s.status='completed' AND substr(s.sale_date,1,10) >= ? "
             "GROUP BY si.product_id", (since,))
    last = q("SELECT si.product_id, MAX(s.sale_date) AS last_sold FROM sale_items si "
             "JOIN sales s ON s.id=si.sale_id WHERE s.status='completed' "
             "GROUP BY si.product_id")
    df = p.merge(soh, left_on="id", right_on="product_id", how="left").drop(columns=["product_id"])
    df = df.merge(sold, left_on="id", right_on="product_id", how="left").drop(columns=["product_id"])
    df = df.merge(last, left_on="id", right_on="product_id", how="left").drop(columns=["product_id"])
    df["soh"] = df["soh"].fillna(0.0)
    df["sold30"] = df["sold30"].fillna(0.0)
    df["rev30"] = df["rev30"].fillna(0.0)
    df["last_sold"] = df["last_sold"].fillna("").map(lambda s: s[:10] if s else "—")
    df["stock_value"] = df["soh"].clip(lower=0) * df["cost_price"]
    df["retail_value"] = df["soh"].clip(lower=0) * df["sell_price"]
    # Margin is worked out on the selling price excluding VAT, because cost prices are
    # booked excluding VAT (input VAT is claimed back from BURS).
    df["price_ex_vat"] = df["sell_price"].map(price_ex_vat)
    df["margin_pct"] = df.apply(
        lambda r: (100 * (r["price_ex_vat"] - r["cost_price"]) / r["price_ex_vat"])
        if r["price_ex_vat"] > 0 else 0.0, axis=1)
    lv = [product_status(s, r) for s, r in zip(df["soh"], df["reorder_level"])]
    df["level"] = [x[0] for x in lv]
    df["color"] = [x[1] for x in lv]
    # days of stock left at the 30-day average sales rate
    df["days_left"] = df.apply(
        lambda r: (r["soh"] / (r["sold30"] / 30.0)) if r["sold30"] > 0 and r["soh"] > 0 else None,
        axis=1)
    for col in ("category", "brand", "sku", "sell_unit"):
        df[col] = df[col].fillna("")
    return df.reset_index(drop=True)


def product_label(r):
    unit = r["sell_unit"] or "unit"
    return f"{r['name']}  ·  {money(r['sell_price'])}/{unit}  ·  {fmt(r['soh'])} in stock"


def adjust_stock(pid, qty, reason, note=""):
    """Manual correction: positive adds stock, negative removes (damage, theft, count)."""
    p = get_product(pid)
    c = get_conn()
    c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, unit_cost, note, user, "
              "logged_at) VALUES(?,?,?,?,?,?,?,?)",
              (int(pid), today_local().isoformat(), float(qty), "adjust",
               float(p["cost_price"]) if p is not None else 0.0,
               (reason + (f" — {note}" if note else "")).strip(" —"), cashier_name(), stamp()))
    c.commit()


def open_bag(bag_pid, bags, loose_pid):
    """Open `bags` sealed bags and move their contents into the loose (per-kg) product.
    The loose product's cost is re-averaged from the bag cost."""
    bag = get_product(bag_pid)
    loose = get_product(loose_pid)
    if bag is None or loose is None:
        raise ValueError("Product not found.")
    kg = float(bag["pack_size"] or 0) * float(bags)
    if kg <= 0:
        raise ValueError("Set the bag's pack size (kg) before opening it.")
    unit_cost_kg = float(bag["cost_price"]) / float(bag["pack_size"])
    soh_loose = stock_on_hand(loose_pid)
    new_cost = ((max(soh_loose, 0) * float(loose["cost_price"]) + kg * unit_cost_kg)
                / (max(soh_loose, 0) + kg))
    c = get_conn()
    d = today_local().isoformat()
    c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, unit_cost, note, user, "
              "logged_at) VALUES(?,?,?,?,?,?,?,?)",
              (int(bag_pid), d, -float(bags), "open_bag_out", float(bag["cost_price"]),
               f"Opened into {loose['name']}", cashier_name(), stamp()))
    c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, unit_cost, note, user, "
              "logged_at) VALUES(?,?,?,?,?,?,?,?)",
              (int(loose_pid), d, kg, "open_bag_in", unit_cost_kg,
               f"From {fmt(bags)} × {bag['name']}", cashier_name(), stamp()))
    c.execute("UPDATE products SET cost_price=? WHERE id=?", (round(new_cost, 4), int(loose_pid)))
    c.commit()
    return kg


# ──────────────────────────────────────────────
# SUPPLIERS & RECEIVING
# ──────────────────────────────────────────────
def get_or_create_supplier(name):
    name = (name or "").strip()
    if not name:
        return None
    c = get_conn()
    row = c.execute("SELECT id FROM suppliers WHERE lower(name)=lower(?)", (name,)).fetchone()
    if row:
        return row[0]
    cur = c.execute("INSERT INTO suppliers(name, created_at) VALUES(?, ?)", (name, stamp()))
    c.commit()
    return cur.lastrowid


def supplier_fields(col_pick, col_new, default_id=None, key=None):
    """Supplier picker for forms: choose an existing supplier or type a new name.
    Returns (picked_id_or_None, new_name). Resolve with resolve_supplier()."""
    sups = q("SELECT id, name FROM suppliers ORDER BY name")
    opts = [None] + sups["id"].astype(int).tolist()
    names = dict(zip(sups["id"].astype(int), sups["name"]))
    idx = opts.index(int(default_id)) if default_id is not None and not pd.isna(default_id) \
        and int(default_id) in opts else 0
    kw = {"key": key} if key else {}
    pick = col_pick.selectbox("Supplier", opts, index=idx,
                              format_func=lambda i: "— none —" if i is None else names[i],
                              help="Who you bought it from. Their total under Suppliers → "
                                   "“Bought (at cost)” goes up by quantity × cost.", **kw)
    new = col_new.text_input("…or a new supplier", placeholder="type a name to add a supplier",
                             **({"key": key + "_new"} if key else {}))
    return pick, new


def resolve_supplier(pick, new):
    """A typed new name wins over the list; it's created if it doesn't exist yet."""
    return get_or_create_supplier(new) if (new or "").strip() else pick


def supplier_name(sid):
    if sid is None or (isinstance(sid, float) and pd.isna(sid)):
        return ""
    r = get_conn().execute("SELECT name FROM suppliers WHERE id=?", (int(sid),)).fetchone()
    return r[0] if r else ""


def receive_stock(pid, qty, unit_cost, supplier_id=None, d=None, batch="", expiry="",
                  invoice_ref="", note="", new_sell_price=None):
    """Book a delivery: adds stock, records the batch/expiry, re-averages cost price."""
    qty, unit_cost = float(qty), float(unit_cost)
    d = d or today_local()
    p = get_product(pid)
    soh = stock_on_hand(pid)
    old_cost = float(p["cost_price"] or 0)
    base = max(soh, 0.0)
    new_cost = ((base * old_cost + qty * unit_cost) / (base + qty)) if (base + qty) > 0 else unit_cost
    c = get_conn()
    cur = c.execute(
        "INSERT INTO receipts(product_id, supplier_id, receive_date, qty, unit_cost, batch, "
        "expiry_date, invoice_ref, note, user, logged_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
        (int(pid), supplier_id, d.isoformat(), qty, unit_cost, batch, expiry or "",
         invoice_ref, note, cashier_name(), stamp()))
    rid = cur.lastrowid
    c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, ref_id, unit_cost, note, "
              "user, logged_at) VALUES(?,?,?,?,?,?,?,?,?)",
              (int(pid), d.isoformat(), qty, "receive", rid, unit_cost,
               invoice_ref or "Delivery", cashier_name(), stamp()))
    c.execute("UPDATE products SET cost_price=? WHERE id=?", (round(new_cost, 4), int(pid)))
    if supplier_id:      # remember who supplies this product, for next time
        c.execute("UPDATE products SET supplier_id=? WHERE id=?", (int(supplier_id), int(pid)))
    if new_sell_price is not None and float(new_sell_price) > 0:
        c.execute("UPDATE products SET sell_price=? WHERE id=?", (float(new_sell_price), int(pid)))
    c.commit()
    return rid


def delete_receipt(rid):
    """Remove a delivery booked by mistake (stock comes back out; cost is left as is)."""
    c = get_conn()
    c.execute("DELETE FROM stock_moves WHERE kind='receive' AND ref_id=?", (int(rid),))
    c.execute("DELETE FROM receipts WHERE id=?", (int(rid),))
    c.commit()


def batch_table():
    """Batches still (estimated to be) on the shelf, assuming first-expiry-first-out:
    the stock on hand is made up of the most recently expiring deliveries."""
    rec = q("SELECT r.*, p.name AS product, p.sell_unit FROM receipts r "
            "JOIN products p ON p.id=r.product_id WHERE p.active=1")
    if rec.empty:
        return pd.DataFrame()
    rows = []
    for pid, grp in rec.groupby("product_id"):
        left = stock_on_hand(pid)
        g = grp.copy()
        g["_k"] = g.apply(lambda r: (r["expiry_date"] or "9999-12-31", r["receive_date"]), axis=1)
        g = g.sort_values("_k", ascending=False)
        for _, r in g.iterrows():
            if left <= 0:
                break
            take = min(float(r["qty"]), left)
            left -= take
            rows.append({"product_id": pid, "Product": r["product"], "Batch": r["batch"] or "—",
                         "Received": r["receive_date"], "Expiry": r["expiry_date"] or "",
                         "On shelf": take, "Unit": r["sell_unit"]})
    return pd.DataFrame(rows)


def expiring_batches(days=30):
    bt = batch_table()
    if bt.empty:
        return bt
    bt = bt[bt["Expiry"].astype(str).str.len() >= 10].copy()
    if bt.empty:
        return bt
    t = today_local()
    bt["days"] = bt["Expiry"].map(lambda s: (date.fromisoformat(s[:10]) - t).days)
    bt = bt[bt["days"] <= days].sort_values("days")
    bt["When"] = bt["days"].map(lambda d: f"expired {-d} day(s) ago" if d < 0
                                else ("expires today" if d == 0 else f"in {d} day(s)"))
    return bt


