def add_customer(name, phone="", village="", credit_limit=0.0, notes=""):
    c = get_conn()
    cur = c.execute("INSERT INTO customers(name, phone, village, credit_limit, notes, created_at) "
                    "VALUES(?,?,?,?,?,?)", (name.strip(), phone, village, float(credit_limit or 0),
                                            notes, stamp()))
    c.commit()
    return cur.lastrowid


def customer_balances():
    """Every customer with what they owe: credit sold (unpaid part of account sales)
    minus payments received."""
    cust = q("SELECT * FROM customers ORDER BY name")
    if cust.empty:
        return cust
    owed = q("SELECT customer_id, SUM(total - paid) AS charged, MAX(sale_date) AS last_sale "
             "FROM sales WHERE status='completed' AND customer_id IS NOT NULL "
             "GROUP BY customer_id")
    paid = q("SELECT customer_id, SUM(amount) AS paid, MAX(pay_date) AS last_payment "
             "FROM payments GROUP BY customer_id")
    df = cust.merge(owed, left_on="id", right_on="customer_id", how="left").drop(columns=["customer_id"])
    df = df.merge(paid, left_on="id", right_on="customer_id", how="left").drop(columns=["customer_id"])
    df["charged"] = df["charged"].fillna(0.0)
    df["paid"] = df["paid"].fillna(0.0)
    df["balance"] = (df["charged"] - df["paid"]).round(2)
    df["last_sale"] = df["last_sale"].fillna("").map(lambda s: s[:10] if s else "—")
    df["last_payment"] = df["last_payment"].fillna("—")
    return df


def customer_balance(cid):
    b = customer_balances()
    if b.empty:
        return 0.0
    m = b[b["id"] == int(cid)]
    return 0.0 if m.empty else float(m.iloc[0]["balance"])


def record_payment(cid, amount, method="Cash", d=None, note=""):
    c = get_conn()
    c.execute("INSERT INTO payments(customer_id, pay_date, amount, method, note, user, logged_at) "
              "VALUES(?,?,?,?,?,?,?)", (int(cid), (d or today_local()).isoformat(), float(amount),
                                        method, note, cashier_name(), stamp()))
    c.commit()


def open_credit_sales(cid=None):
    """Credit sales that are not yet fully paid, oldest first. A customer's payments are
    applied to their oldest unpaid sale first, so each row shows what is still owing on it."""
    s = q("SELECT s.id, s.sale_no, s.sale_date, s.customer_id, c.name AS customer, "
          "c.phone, c.village, s.total, s.paid FROM sales s JOIN customers c "
          "ON c.id=s.customer_id WHERE s.status='completed' AND s.total - s.paid > 0.004 "
          + ("AND s.customer_id=? " if cid else "") + "ORDER BY s.sale_date, s.id",
          (int(cid),) if cid else ())
    cols = ["sale_id", "Date", "Receipt", "customer_id", "Customer", "Phone", "Village",
            "Items", "Sale total", "Paid", "Still owing", "Days"]
    if s.empty:
        return pd.DataFrame(columns=cols)
    pays = q("SELECT customer_id, SUM(amount) AS amt FROM payments GROUP BY customer_id")
    credit = {int(a): float(b) for a, b in zip(pays["customer_id"], pays["amt"])}
    items = q("SELECT sale_id, name, qty FROM sale_items WHERE sale_id IN (%s)"
              % ",".join(str(int(i)) for i in s["id"]))
    desc = {sid: ", ".join(f"{fmt(r['qty'])} × {r['name']}" for _, r in g.iterrows())
            for sid, g in items.groupby("sale_id")}
    t = today_local()
    rows = []
    for _, r in s.iterrows():
        c_ = int(r["customer_id"])
        owing = float(r["total"]) - float(r["paid"])
        used = min(credit.get(c_, 0.0), owing)
        credit[c_] = credit.get(c_, 0.0) - used
        left = round(owing - used, 2)
        if left > 0.004:
            rows.append({"sale_id": int(r["id"]), "Date": r["sale_date"][:10],
                         "Receipt": r["sale_no"], "customer_id": c_, "Customer": r["customer"],
                         "Phone": r["phone"] or "", "Village": r["village"] or "",
                         "Items": desc.get(int(r["id"]), ""), "Sale total": float(r["total"]),
                         "Paid": float(r["paid"]) + used, "Still owing": left,
                         "Days": (t - date.fromisoformat(r["sale_date"][:10])).days})
    return pd.DataFrame(rows, columns=cols)


def credit_table_view(df, with_customer=True):
    """Friendly display version of open_credit_sales()."""
    out = pd.DataFrame({"Date": df["Date"], "Receipt": df["Receipt"]})
    if with_customer:
        out["Customer"] = df["Customer"]
        out["Phone"] = df["Phone"]
    out["Items"] = df["Items"]
    out["Sale total"] = df["Sale total"].map(money)
    out["Paid"] = df["Paid"].map(money)
    out["Still owing"] = df["Still owing"].map(money)
    out["Days owing"] = df["Days"]
    return out


def customer_statement_full(cid, start=None, end=None):
    """Complete statement for ONE customer: every completed sale to them (cash or credit,
    with the items) and every payment they made, with a running balance of what they owe.
    Returns (opening_balance, DataFrame). Lines before `start` roll into the opening balance."""
    cid = int(cid)
    sales_ = q("SELECT id, sale_no, sale_date, method, total, paid FROM sales "
               "WHERE status='completed' AND customer_id=? ORDER BY sale_date, id", (cid,))
    pays_ = q("SELECT pay_date, method, note, amount FROM payments WHERE customer_id=? "
              "ORDER BY pay_date, id", (cid,))
    items_ = (q("SELECT sale_id, name, qty FROM sale_items WHERE sale_id IN (%s) ORDER BY id"
                % ",".join(str(int(i)) for i in sales_["id"])) if not sales_.empty
              else pd.DataFrame(columns=["sale_id", "name", "qty"]))
    desc = {sid: ", ".join(f"{fmt(r['qty'])} × {r['name']}" for _, r in g.iterrows())
            for sid, g in items_.groupby("sale_id")}
    ev = []
    for _, r in sales_.iterrows():
        ev.append({"_t": r["sale_date"], "Date": r["sale_date"][:10], "Receipt": r["sale_no"],
                   "Details": desc.get(int(r["id"]), ""),
                   "Paid by": "On credit" if r["method"] == ACCOUNT_METHOD else r["method"],
                   "Sale total": float(r["total"]), "Paid at sale": float(r["paid"]),
                   "Payment received": 0.0})
    for _, r in pays_.iterrows():
        ev.append({"_t": r["pay_date"] + "T99", "Date": r["pay_date"], "Receipt": "",
                   "Details": "Payment received" + (f" — {r['note']}" if r["note"] else ""),
                   "Paid by": r["method"], "Sale total": 0.0, "Paid at sale": 0.0,
                   "Payment received": float(r["amount"])})
    cols = ["Date", "Receipt", "Details", "Paid by", "Sale total", "Paid at sale",
            "Payment received", "Owing"]
    if not ev:
        return 0.0, pd.DataFrame(columns=cols)
    df = pd.DataFrame(ev).sort_values("_t", kind="stable").reset_index(drop=True)
    df["Owing"] = (df["Sale total"] - df["Paid at sale"] - df["Payment received"]).cumsum().round(2)
    opening = 0.0
    if start is not None:
        before = df[df["Date"] < start.isoformat()]
        opening = float(before["Owing"].iloc[-1]) if not before.empty else 0.0
        df = df[df["Date"] >= start.isoformat()]
    if end is not None:
        df = df[df["Date"] <= end.isoformat()]
    return opening, df[cols].reset_index(drop=True)


def customer_statement(cid):
    """Running account for one customer: account sales (debits) and payments (credits)."""
    s = q("SELECT sale_date AS date, sale_no AS ref, total, paid FROM sales "
          "WHERE status='completed' AND customer_id=?", (int(cid),))
    p = q("SELECT pay_date AS date, method, note, amount FROM payments WHERE customer_id=?",
          (int(cid),))
    rows = []
    for _, r in s.iterrows():
        owed = float(r["total"]) - float(r["paid"])
        if owed > 0.004:
            rows.append({"Date": r["date"][:10], "Detail": f"Sale {r['ref']} "
                         f"(total {money(r['total'])}, paid {money(r['paid'])})",
                         "Debit": owed, "Credit": 0.0, "_t": r["date"]})
    for _, r in p.iterrows():
        rows.append({"Date": r["date"][:10], "Detail": f"Payment — {r['method']}"
                     + (f" ({r['note']})" if r["note"] else ""),
                     "Debit": 0.0, "Credit": float(r["amount"]), "_t": r["date"] + "T99"})
    if not rows:
        return pd.DataFrame(columns=["Date", "Detail", "Debit", "Credit", "Balance"])
    df = pd.DataFrame(rows).sort_values("_t").drop(columns=["_t"]).reset_index(drop=True)
    df["Balance"] = (df["Debit"] - df["Credit"]).cumsum().round(2)
    return df


# ──────────────────────────────────────────────
# SALES
# ──────────────────────────────────────────────
def cart_totals(cart, invoice_discount=0.0):
    """Return dict(subtotal, discount, net, vat, total) for a cart.
    subtotal is after line discounts; discount is the whole-sale discount."""
    sub = sum(max(0.0, float(l["qty"]) * float(l["price"]) - float(l.get("disc", 0) or 0))
              for l in cart)
    disc = min(max(0.0, float(invoice_discount or 0)), sub)
    net = sub - disc
    rate, mode = vat_rate(), vat_mode()
    if mode == "exclusive":
        vat = net * rate / 100.0
        total = net + vat
    elif mode == "inclusive":
        total = net
        vat = total * rate / (100.0 + rate)
    else:
        vat, total = 0.0, net
    return {"subtotal": r2(sub), "discount": r2(disc), "net": r2(net),
            "vat": r2(vat), "total": r2(total)}


def check_stock(cart):
    """List of human-readable problems where the cart asks for more than is on the shelf."""
    need = {}
    for l in cart:
        need[l["pid"]] = need.get(l["pid"], 0.0) + float(l["qty"])
    issues = []
    for pid, qty in need.items():
        soh = stock_on_hand(pid)
        if qty > soh + 1e-9:
            p = get_product(pid)
            issues.append(f"{p['name']}: selling {fmt(qty)} but only {fmt(soh)} in stock")
    return issues


def create_sale(cart, method, customer_id=None, invoice_discount=0.0, tendered=0.0,
                paid_now=None, note="", when=None):
    """Write a completed sale, its lines and the stock movements. Returns sale id."""
    if not cart:
        raise ValueError("Nothing to sell.")
    t = cart_totals(cart, invoice_discount)
    total = t["total"]
    if method == ACCOUNT_METHOD:
        if not customer_id:
            raise ValueError("Choose a customer for an account (credit) sale.")
        paid = min(max(0.0, float(paid_now or 0)), total)
        tendered_v, change = paid, 0.0
    elif method == "Cash":
        tendered_v = float(tendered or 0) if float(tendered or 0) > 0 else total
        if tendered_v + 1e-9 < total:
            raise ValueError(f"Cash received ({money(tendered_v)}) is less than the total "
                             f"({money(total)}).")
        paid, change = total, r2(tendered_v - total)
    else:
        paid, tendered_v, change = total, total, 0.0
    when = when or now_local()
    c = get_conn()
    try:
        cur = c.execute(
            "INSERT INTO sales(sale_no, sale_date, customer_id, cashier, subtotal, discount, vat, "
            "total, paid, tendered, change_given, method, status, note, logged_at) "
            "VALUES('', ?,?,?,?,?,?,?,?,?,?,?,'completed',?,?)",
            (when.isoformat(timespec="seconds"), customer_id, cashier_name(), t["subtotal"],
             t["discount"], t["vat"], total, r2(paid), r2(tendered_v), change, method, note,
             stamp()))
        sid = cur.lastrowid
        sale_no = f"S{sid:06d}"
        c.execute("UPDATE sales SET sale_no=? WHERE id=?", (sale_no, sid))
        for l in cart:
            p = get_product(l["pid"])
            line = max(0.0, float(l["qty"]) * float(l["price"]) - float(l.get("disc", 0) or 0))
            c.execute("INSERT INTO sale_items(sale_id, product_id, name, qty, unit_price, discount, "
                      "line_total, unit_cost) VALUES(?,?,?,?,?,?,?,?)",
                      (sid, int(l["pid"]), p["name"], float(l["qty"]), float(l["price"]),
                       float(l.get("disc", 0) or 0), r2(line), float(p["cost_price"] or 0)))
            c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, ref_id, unit_cost, "
                      "note, user, logged_at) VALUES(?,?,?,?,?,?,?,?,?)",
                      (int(l["pid"]), when.date().isoformat(), -float(l["qty"]), "sale", sid,
                       float(p["cost_price"] or 0), sale_no, cashier_name(), stamp()))
        c.commit()
    except Exception:
        c.rollback()
        raise
    return sid


def void_sale(sid, reason):
    """Cancel a sale: stock goes back on the shelf; it drops out of takings and any
    account balance."""
    c = get_conn()
    s = c.execute("SELECT status, sale_no FROM sales WHERE id=?", (int(sid),)).fetchone()
    if not s or s[0] != "completed":
        return False
    items = c.execute("SELECT product_id, qty, unit_cost FROM sale_items WHERE sale_id=?",
                      (int(sid),)).fetchall()
    for pid, qty, ucost in items:
        c.execute("INSERT INTO stock_moves(product_id, move_date, qty, kind, ref_id, unit_cost, "
                  "note, user, logged_at) VALUES(?,?,?,?,?,?,?,?,?)",
                  (pid, today_local().isoformat(), float(qty), "void", int(sid), ucost or 0,
                   f"Void of {s[1]}", cashier_name(), stamp()))
    c.execute("UPDATE sales SET status='voided', void_reason=? WHERE id=?",
              (reason or "", int(sid)))
    c.commit()
    return True


def sales_frame(start=None, end=None, include_voided=False):
    """Sales with customer name and cost-of-goods / profit per sale."""
    where, params = [], []
    if start:
        where.append("substr(s.sale_date,1,10) >= ?")
        params.append(start.isoformat())
    if end:
        where.append("substr(s.sale_date,1,10) <= ?")
        params.append(end.isoformat())
    if not include_voided:
        where.append("s.status='completed'")
    sql = ("SELECT s.*, COALESCE(c.name,'Walk-in') AS customer, "
           "(SELECT COALESCE(SUM(qty*unit_cost),0) FROM sale_items WHERE sale_id=s.id) AS cogs, "
           "(SELECT COALESCE(SUM(qty),0) FROM sale_items WHERE sale_id=s.id) AS units "
           "FROM sales s LEFT JOIN customers c ON c.id=s.customer_id")
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY s.sale_date DESC, s.id DESC"
    df = q(sql, params)
    if df.empty:
        return df
    df["day"] = df["sale_date"].str[:10]
    df["net_ex_vat"] = df["total"] - df["vat"]
    df["profit"] = df["net_ex_vat"] - df["cogs"]
    return df


def items_frame(start=None, end=None):
    where, params = ["s.status='completed'"], []
    if start:
        where.append("substr(s.sale_date,1,10) >= ?")
        params.append(start.isoformat())
    if end:
        where.append("substr(s.sale_date,1,10) <= ?")
        params.append(end.isoformat())
    df = q("SELECT si.*, s.sale_no, s.sale_date, s.method, s.cashier, s.total AS sale_total, "
           "s.vat AS sale_vat, COALESCE(p.category,'') AS category, "
           "COALESCE(p.sell_unit,'') AS sell_unit "
           "FROM sale_items si JOIN sales s ON s.id=si.sale_id "
           "LEFT JOIN products p ON p.id=si.product_id WHERE " + " AND ".join(where), params)
    if df.empty:
        return df
    # Share each sale's whole-sale discount and VAT across its lines so revenue
    # figures per product add up to the till takings (ex-VAT).
    line_sum = df.groupby("sale_id")["line_total"].transform("sum").replace(0, 1)
    share = df["line_total"] / line_sum
    df["revenue_ex_vat"] = (df["sale_total"] - df["sale_vat"]) * share
    df["cogs"] = df["qty"] * df["unit_cost"]
    df["profit"] = df["revenue_ex_vat"] - df["cogs"]
    return df


# ──────────────────────────────────────────────
# BACKUP & RESTORE
# ──────────────────────────────────────────────
DB_TABLES = ["settings", "products", "suppliers", "customers", "receipts", "stock_moves",
             "sales", "sale_items", "payments"]


def backup_bytes():
    """A consistent snapshot of the whole database (safe even while the app is in use)."""
    tmp = tempfile.NamedTemporaryFile(suffix=".db", delete=False)
    tmp.close()
    try:
        dst = sqlite3.connect(tmp.name)
        get_conn().backup(dst)
        dst.close()
        with open(tmp.name, "rb") as fh:
            return fh.read()
    finally:
        try:
            os.remove(tmp.name)
        except OSError:
            pass


def restore_from_bytes(data):
    """Validate an uploaded backup and replace the live database with it.
    A safety copy of the current data is kept next to the database first.
    Returns (ok, message)."""
    if not data or data[:16] != b"SQLite format 3\x00":
        return False, "That file isn't a Sales Manager backup (it's not a database file)."
    tmp = tempfile.NamedTemporaryFile(suffix=".db", delete=False)
    tmp.write(data)
    tmp.close()
    try:
        chk = sqlite3.connect(tmp.name)
        names = {r[0] for r in chk.execute(
            "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        ok_int = chk.execute("PRAGMA quick_check").fetchone()[0]
        n_sales = chk.execute("SELECT COUNT(*) FROM sales").fetchone()[0] \
            if "sales" in names else 0
        n_prod = chk.execute("SELECT COUNT(*) FROM products").fetchone()[0] \
            if "products" in names else 0
        chk.close()
    except Exception as e:
        try:
            os.remove(tmp.name)
        except OSError:
            pass
        return False, f"Couldn't read that backup: {e}"
    missing = set(DB_TABLES) - names
    if missing or ok_int != "ok":
        try:
            os.remove(tmp.name)
        except OSError:
            pass
        return False, ("That file doesn't look like a Sales Manager backup"
                       + (f" (missing: {', '.join(sorted(missing))})." if missing
                          else " (the file is damaged)."))
    was_active = is_activated()
    safety = os.path.join(os.path.dirname(os.path.abspath(DB_PATH)) or ".",
                          f"before-restore-{now_local():%Y%m%d-%H%M%S}.db")
    try:
        with open(safety, "wb") as fh:
            fh.write(backup_bytes())
    except Exception:
        safety = ""
    try:
        get_conn().close()
    except Exception:
        pass
    try:
        get_conn.clear()
    except Exception:
        pass
    shutil.move(tmp.name, DB_PATH)
    for ext in ("-wal", "-shm"):
        side = DB_PATH + ext
        if os.path.exists(side):
            try:
                os.remove(side)
            except OSError:
                pass
    init_db()                       # brings an older backup up to the current layout
    if was_active:                  # keep this computer activated after the swap
        activate_this_computer()
    return True, (f"Backup restored — {n_prod} product(s) and {n_sales} sale(s)."
                  + (f" Your previous data was kept as {os.path.basename(safety)}."
                     if safety else ""))


