def expenses_frame(start=None, end=None):
    where, params = [], []
    if start:
        where.append("exp_date >= ?")
        params.append(start.isoformat())
    if end:
        where.append("exp_date <= ?")
        params.append(end.isoformat())
    return q("SELECT * FROM expenses" + (" WHERE " + " AND ".join(where) if where else "")
             + " ORDER BY exp_date DESC, id DESC", params)


def expenses_total(start, end):
    v = get_conn().execute("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE exp_date "
                           "BETWEEN ? AND ?", (start.isoformat(), end.isoformat())).fetchone()[0]
    return float(v or 0)


def month_start(d, back=0):
    """First day of the month `back` months before d's month (negative = later)."""
    y, m = d.year, d.month - back
    while m <= 0:
        m += 12
        y -= 1
    while m > 12:
        m -= 12
        y += 1
    return date(y, m, 1)


def month_end(d):
    return month_start(d, -1) - timedelta(days=1)


