def _store_logo_bytes():
    b = get_setting("store_logo_b64", "")
    if b:
        try:
            return _b64.b64decode(b)
        except Exception:
            return None
    return None


def make_pdf(title, subtitle, sections, landscape_mode=False):
    """Branded A4 report. sections = [(heading, DataFrame | str), ...]."""
    try:
        from reportlab.lib import colors as _rlc
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.units import mm
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer, Table,
                                        TableStyle, Image as _RLImage)
    except Exception:
        return None
    buf = _io.BytesIO()
    page = landscape(A4) if landscape_mode else A4
    doc = SimpleDocTemplate(buf, pagesize=page, title=title, leftMargin=14 * mm,
                            rightMargin=14 * mm, topMargin=12 * mm, bottomMargin=14 * mm)
    ss = getSampleStyleSheet()
    h1 = ParagraphStyle("h1", parent=ss["Title"], fontSize=17, alignment=0,
                        textColor=_rlc.HexColor(PRIMARY), spaceAfter=1)
    small = ParagraphStyle("small", parent=ss["Normal"], fontSize=8.5,
                           textColor=_rlc.HexColor(MUTED), spaceAfter=2)
    h2 = ParagraphStyle("h2", parent=ss["Heading2"], fontSize=12,
                        textColor=_rlc.HexColor(PRIMARY), spaceBefore=10, spaceAfter=4)
    cell = ParagraphStyle("cell", parent=ss["Normal"], fontSize=8, leading=10)
    story = []
    logo = _store_logo_bytes()
    if logo:
        try:
            from PIL import Image as _P
            w, h = _P.open(_io.BytesIO(logo)).size
            lw = 40 * mm
            img = _RLImage(_io.BytesIO(logo), width=lw, height=lw * h / max(w, 1))
            img.hAlign = "LEFT"
            story.append(img)
        except Exception:
            pass
    story.append(Paragraph(_esc(store_name()), small))
    story.append(Paragraph(_esc(title), h1))
    story.append(Paragraph(_esc(subtitle), small))
    story.append(Paragraph(f"Generated {now_local():%d %b %Y, %H:%M}"
                           + (f" by {_esc(cashier_name())}" if cashier_name() else ""), small))
    story.append(Spacer(1, 4))
    for heading, content in sections:
        story.append(Paragraph(_esc(heading), h2))
        if isinstance(content, str):
            story.append(Paragraph(_esc(content).replace("\n", "<br/>") or "—",
                                   ParagraphStyle("b", parent=ss["Normal"], fontSize=10,
                                                  leading=14)))
            continue
        df = content
        if df is None or len(df) == 0:
            story.append(Paragraph("No data.", cell))
            continue
        head = [Paragraph(f'<font color="#FFFFFF"><b>{_esc(c)}</b></font>', cell)
                for c in df.columns]
        body = [[Paragraph(_esc(v), cell) for v in row] for row in df.astype(str).values.tolist()]
        t = Table([head] + body, repeatRows=1, hAlign="LEFT")
        t.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), _rlc.HexColor(PRIMARY)),
            ("ROWBACKGROUNDS", (0, 1), (-1, -1), [_rlc.white, _rlc.HexColor(LIGHT_BG)]),
            ("GRID", (0, 0), (-1, -1), 0.4, _rlc.HexColor(GRID)),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
            ("LEFTPADDING", (0, 0), (-1, -1), 4), ("RIGHTPADDING", (0, 0), (-1, -1), 4),
            ("TOPPADDING", (0, 0), (-1, -1), 3), ("BOTTOMPADDING", (0, 0), (-1, -1), 3)]))
        story.append(t)
    disc = ParagraphStyle("disc", parent=ss["Normal"], fontSize=7.2, leading=9.5,
                          textColor=_rlc.HexColor(MUTED), spaceBefore=12)
    story.append(Spacer(1, 10))
    story.append(Paragraph(f"<i>Report generated by Sales Manager for {_esc(store_name())}.</i> "
                           f"A product of Health Data Matrics.", disc))
    doc.build(story)
    return buf.getvalue()


def _esc(s):
    return (str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))


def receipt_lines(sale_id):
    """The content of a receipt as (kind, left, right) lines — shared by the PDF and the
    on-screen view so both always match."""
    sdf = q("SELECT s.*, c.name AS customer, c.phone AS cphone FROM sales s "
            "LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=?", (int(sale_id),))
    if sdf.empty:
        return None
    s = sdf.iloc[0]
    items = q("SELECT * FROM sale_items WHERE sale_id=? ORDER BY id", (int(sale_id),))
    cur = currency()
    lines = []  # (kind, left, right)

    def add(kind, left="", right=""):
        lines.append((kind, left, right))

    add("title", store_name())
    for k in ("store_address", "store_phone"):
        v = get_setting(k, "")
        for part in str(v).splitlines():
            if part.strip():
                add("center", part.strip())
    vat_no = get_setting("vat_no", "")
    if vat_no and vat_mode() != "none":
        add("center", f"VAT No: {vat_no}")
    add("rule")
    add("center", "TAX INVOICE" if vat_mode() != "none" else "SALES RECEIPT")
    if s["status"] == "voided":
        add("bold_center", "*** VOIDED ***")
    add("lr", f"Receipt {s['sale_no']}", s["sale_date"][:16].replace("T", " "))
    if s["cashier"]:
        add("lr", "Served by", s["cashier"])
    if s["customer"]:
        add("lr", "Customer", s["customer"])
    add("rule")
    for _, it in items.iterrows():
        add("left", it["name"])
        add("lr", f"  {fmt(it['qty'])} x {cur} {float(it['unit_price']):,.2f}",
            f"{float(it['qty']) * float(it['unit_price']):,.2f}")
        if float(it["discount"] or 0) > 0:
            add("lr", "  less discount", f"-{float(it['discount']):,.2f}")
    add("rule")
    add("lr", "Subtotal", f"{float(s['subtotal']):,.2f}")
    if float(s["discount"]) > 0:
        add("lr", "Discount", f"-{float(s['discount']):,.2f}")
    if vat_mode() == "exclusive":
        add("lr", f"VAT {vat_rate():g}%", f"{float(s['vat']):,.2f}")
    add("big", "TOTAL", f"{cur} {float(s['total']):,.2f}")
    if vat_mode() == "inclusive":
        add("lr", f"Incl. VAT {vat_rate():g}%", f"{float(s['vat']):,.2f}")
    add("rule")
    add("lr", "Paid by", s["method"])
    if s["method"] == "Cash":
        add("lr", "Cash received", f"{float(s['tendered']):,.2f}")
        add("lr", "Change", f"{float(s['change_given']):,.2f}")
    elif s["method"] == ACCOUNT_METHOD:
        add("lr", "Paid now", f"{float(s['paid']):,.2f}")
        add("lr", "Charged to account", f"{float(s['total']) - float(s['paid']):,.2f}")
        if s["customer_id"] and not pd.isna(s["customer_id"]):
            add("lr", "Account balance", f"{customer_balance(int(s['customer_id'])):,.2f}")
    add("rule")
    footer = get_setting("receipt_footer", "Thank you for your support! Ke a leboga.")
    for part in footer.splitlines():
        if part.strip():
            add("center", part.strip())
    add("small_center", "Powered by Health Data Matrics")
    return lines


def make_receipt_pdf(sale_id):
    """An 80 mm till-roll receipt (prints on thermal printers, also fine as a PDF)."""
    try:
        from reportlab.pdfgen import canvas
        from reportlab.lib.units import mm
    except Exception:
        return None
    lines = receipt_lines(sale_id)
    if not lines:
        return None
    W = 80 * mm
    height = (14 + sum(9 if k in ("title", "big") else (3 if k == "rule" else 4.6)
                       for k, _, _ in lines)) * mm
    buf = _io.BytesIO()
    cv = canvas.Canvas(buf, pagesize=(W, height))
    y = height - 7 * mm
    left_x, right_x = 4 * mm, W - 4 * mm
    for kind, left, right in lines:
        if kind == "title":
            cv.setFont("Helvetica-Bold", 12)
            cv.drawCentredString(W / 2, y - 2 * mm, str(left)[:36])
            y -= 9 * mm
        elif kind in ("center", "bold_center", "small_center"):
            cv.setFont("Helvetica-Bold" if kind == "bold_center" else "Helvetica",
                       6.5 if kind == "small_center" else 8)
            cv.drawCentredString(W / 2, y, str(left)[:52])
            y -= 4.6 * mm
        elif kind == "left":
            cv.setFont("Helvetica-Bold", 8)
            cv.drawString(left_x, y, str(left)[:46])
            y -= 4.6 * mm
        elif kind == "lr":
            cv.setFont("Helvetica", 8)
            cv.drawString(left_x, y, str(left)[:34])
            cv.drawRightString(right_x, y, str(right)[:22])
            y -= 4.6 * mm
        elif kind == "big":
            cv.setFont("Helvetica-Bold", 12)
            cv.drawString(left_x, y - 2 * mm, str(left))
            cv.drawRightString(right_x, y - 2 * mm, str(right))
            y -= 9 * mm
        elif kind == "rule":
            cv.setDash(1, 2)
            cv.line(left_x, y + 1.5 * mm, right_x, y + 1.5 * mm)
            cv.setDash()
            y -= 3 * mm
    cv.showPage()
    cv.save()
    return buf.getvalue()


def receipt_html(sale_id):
    """The receipt as an on-screen till slip."""
    lines = receipt_lines(sale_id)
    if not lines:
        return ""
    out = []
    for kind, left, right in lines:
        l_, r_ = _esc(left), _esc(right)
        if kind == "title":
            out.append(f'<div class="rc-title">{l_}</div>')
        elif kind == "center":
            out.append(f'<div class="rc-center">{l_}</div>')
        elif kind == "bold_center":
            out.append(f'<div class="rc-center rc-void">{l_}</div>')
        elif kind == "small_center":
            out.append(f'<div class="rc-center rc-small">{l_}</div>')
        elif kind == "left":
            out.append(f'<div class="rc-item">{l_}</div>')
        elif kind == "lr":
            out.append(f'<div class="rc-lr"><span>{l_.replace("  ", "&nbsp;&nbsp;")}</span>'
                       f'<span>{r_}</span></div>')
        elif kind == "big":
            out.append(f'<div class="rc-lr rc-big"><span>{l_}</span><span>{r_}</span></div>')
        elif kind == "rule":
            out.append('<div class="rc-rule"></div>')
    return f'<div class="receipt-wrap"><div class="receipt">{"".join(out)}</div></div>'


def show_receipt_actions(sale_id, sale_no, key):
    """Reprint (download) + View/Hide receipt side by side, and the slip when shown."""
    vkey = f"view_rc_{key}"
    open_ = st.session_state.get(vkey) == sale_id
    a, b, _ = st.columns([1.3, 1.1, 2])
    with a:
        save_download("🖨️ Print receipt" if IS_DESKTOP else "🧾 Print / download receipt",
                      make_receipt_pdf(sale_id), f"receipt-{sale_no}.pdf", "application/pdf",
                      key=f"dl_rc_{key}_{sale_id}", use_container_width=True,
                      auto_open=IS_DESKTOP)
    if b.button("🙈 Hide receipt" if open_ else "👁️ View receipt", key=f"btn_rc_{key}",
                use_container_width=True):
        st.session_state[vkey] = None if open_ else sale_id
        st.rerun()
    if open_:
        st.markdown(receipt_html(sale_id), unsafe_allow_html=True)


