# DOWNLOADS (desktop app saves straight to Downloads)
# ──────────────────────────────────────────────
def _downloads_dir():
    home = os.path.expanduser("~")
    if os.name == "nt":
        try:
            import winreg
            with winreg.OpenKey(
                    winreg.HKEY_CURRENT_USER,
                    r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders") as k:
                val, _ = winreg.QueryValueEx(k, "{374DE290-123F-4565-9164-39C4925E467B}")
            val = os.path.expandvars(val)
            if val and os.path.isdir(val):
                return val
        except Exception:
            pass
    d = os.path.join(home, "Downloads")
    try:
        os.makedirs(d, exist_ok=True)
        return d
    except Exception:
        return home


def _unique_path(folder, filename):
    base, ext = os.path.splitext(filename)
    path = os.path.join(folder, filename)
    i = 2
    while os.path.exists(path):
        path = os.path.join(folder, f"{base} ({i}){ext}")
        i += 1
    return path


def _open_path(path):
    """Open a saved file with its usual program (PDF viewer, Excel…) on this computer."""
    try:
        if os.name == "nt":
            os.startfile(path)                                   # noqa: S606
        elif sys.platform == "darwin":
            subprocess.Popen(["open", path])
        else:
            subprocess.Popen(["xdg-open", path])
        return True
    except Exception:
        return False


def save_download(label, data, filename, mime, key, use_container_width=False,
                  auto_open=False):
    """Download button that works everywhere.
    Desktop window (SALES_DESKTOP=1): the file is written straight to the Downloads folder —
    no reliance on the webview's download plumbing — and stays listed with an Open button.
    auto_open opens it at once (used for receipts, so they can be printed).
    Browser / server: an ordinary download button."""
    if data is None:
        st.caption("PDF export needs the 'reportlab' package (pip install reportlab).")
        return
    if IS_DESKTOP:
        saved = st.session_state.setdefault("_saved_files", {})
        if st.button(label, key=key, use_container_width=use_container_width):
            try:
                path = _unique_path(_downloads_dir(), filename)
                mode = "wb" if isinstance(data, (bytes, bytearray)) else "w"
                with open(path, mode, **({} if mode == "wb" else {"encoding": "utf-8"})) as f:
                    f.write(data)
                saved[key] = path
                if auto_open:
                    _open_path(path)
            except Exception as e:
                saved.pop(key, None)
                st.error(f"Could not save the file: {e}")
        if key in saved:
            st.success(f"Saved to Downloads: **{os.path.basename(saved[key])}**\n\n"
                       f"`{saved[key]}`")
            if st.button("📂 Open file", key=f"{key}__open"):
                if not _open_path(saved[key]):
                    st.error("Couldn't open it automatically — find it in your Downloads "
                             "folder.")
    else:
        st.download_button(label, data=data, file_name=filename, mime=mime, key=key,
                           use_container_width=use_container_width)


