def kpi_row(cards):
    """cards = [(icon, label, value, color[, sub[, tone]])]; tone 'good'/'bad' turns the
    sub-line into a green/red pill (for changes vs. an earlier period)."""
    cells = []
    for c in cards:
        icon, label, value, color, sub, tone = (tuple(c) + ("", ""))[:6]
        sub_html = (f'<div class="kpi-sub {tone}">{sub}</div>' if sub else "")
        cells.append(
            f'<div class="kpi-card" style="--kc:{color};--kbg:{color}1A;">'
            f'<div class="kpi-top"><div class="kpi-icon">{icon}</div>'
            f'<div class="kpi-label">{label}</div></div>'
            f'<div class="kpi-value">{value}</div>{sub_html}</div>')
    st.markdown(f'<div class="kpi-row">{"".join(cells)}</div>', unsafe_allow_html=True)


def change_pill(now, before, rising_is_good=True, vs="vs yesterday"):
    """('▲ 12% vs yesterday', 'good') style sub-line for kpi_row."""
    if not before:
        return ("", "")
    ch = (now - before) / before * 100
    up = ch >= 0
    tone = "good" if up == rising_is_good else "bad"
    return (f"{'▲' if up else '▼'} {abs(ch):.0f}% {vs}", tone)


