def _fig_layout(fig, height=300, legend=False):
    fig.update_layout(paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
                      font=dict(color=INK, size=12), height=height,
                      margin=dict(l=8, r=10, t=8, b=30), showlegend=legend,
                      legend=dict(orientation="h", y=1.12, x=0, font=dict(size=11)),
                      hoverlabel=dict(bgcolor="#FFFFFF", bordercolor=GRID,
                                      font=dict(color=INK, size=12)))
    fig.update_xaxes(showgrid=False, zeroline=False, automargin=True, linecolor=GRID)
    fig.update_yaxes(showgrid=True, gridcolor="#EEF4EA", zeroline=False, automargin=True)
    return fig


