def keep_valid(key, options):
    """Forget a remembered selection that is no longer in the list (e.g. a voided sale
    or a paid-up customer), so the selectbox falls back to its first option."""
    if key in st.session_state and st.session_state[key] not in list(options):
        del st.session_state[key]


def tab_bar(key, tabs):
    """Pill-style tab bar for the main content area.
    tabs = [(id, label, hint), ...]. Returns the id of the active tab.
    Unlike st.tabs, the choice is kept in session state, so the page stays on the same tab
    after a form is saved, and only the active tab's content is built (faster)."""
    ids = [t[0] for t in tabs]
    labels = {t[0]: t[1] for t in tabs}
    hints = {t[0]: t[2] for t in tabs}
    pending = st.session_state.pop("_tab_goto", None)
    if pending and pending[0] == key and pending[1] in ids:
        st.session_state[key] = pending[1]
    keep_valid(key, ids)
    active = st.radio("Section", ids, key=key, horizontal=True,
                      format_func=lambda i: labels[i], label_visibility="collapsed")
    if hints.get(active):
        st.markdown(f'<div class="tab-hint">{hints[active]}</div>', unsafe_allow_html=True)
    return active


def go_to(page, tab_key=None, tab_id=None):
    """Jump to another page (and optionally one of its tabs) on the next rerun."""
    st.session_state["_goto"] = page
    if tab_key and tab_id:
        st.session_state["_tab_goto"] = (tab_key, tab_id)
    st.rerun()


def go_to_tab(tab_key, tab_id):
    st.session_state["_tab_goto"] = (tab_key, tab_id)
    st.rerun()


def date_range_picker(key, default_days=30):
    t = today_local()
    presets = ["Today", "Yesterday", "Last 7 days", "Last 30 days", "This month",
               "Last month", "This year", "Custom"]
    c1, c2, c3 = st.columns([2, 2, 2])
    pick = c1.selectbox("Period", presets, index=3 if default_days == 30 else 0, key=f"{key}_p")
    if pick == "Today":
        s, e = t, t
    elif pick == "Yesterday":
        s = e = t - timedelta(days=1)
    elif pick == "Last 7 days":
        s, e = t - timedelta(days=6), t
    elif pick == "Last 30 days":
        s, e = t - timedelta(days=29), t
    elif pick == "This month":
        s, e = t.replace(day=1), t
    elif pick == "Last month":
        e = t.replace(day=1) - timedelta(days=1)
        s = e.replace(day=1)
    elif pick == "This year":
        s, e = t.replace(month=1, day=1), t
    else:
        s, e = t - timedelta(days=29), t
    if pick == "Custom":
        s = c2.date_input("From", value=s, key=f"{key}_from")
        e = c3.date_input("To", value=e, key=f"{key}_to")
    else:
        c2.markdown(f'<div style="padding-top:2rem;color:{MUTED};">{s:%d %b %Y} → {e:%d %b %Y}'
                    f'</div>', unsafe_allow_html=True)
    if s > e:
        s, e = e, s
    return s, e


# ──────────────────────────────────────────────
# ASSISTANT (offline, keyword-based)
# ──────────────────────────────────────────────
def answer_question(question):
    ql = (question or "").lower()
    t = today_local()

    def has(*w):
        return any(x in ql for x in w)

    def period():
        if "yesterday" in ql:
            d = t - timedelta(days=1)
            return d, d, "yesterday"
        if has("this week", "last 7", "past week"):
            return t - timedelta(days=6), t, "in the last 7 days"
        if has("this month", "month"):
            return t.replace(day=1), t, "this month"
        if has("this year", "year"):
            return t.replace(month=1, day=1), t, "this year"
        if has("last 30", "30 days"):
            return t - timedelta(days=29), t, "in the last 30 days"
        return t, t, "today"

    stock = stock_table()
    if has("help", "what can you"):
        return ("Ask me things like: “sales today”, “profit this month”, “best seller this "
                "week”, “what's low on stock”, “how many bags of layer mash”, “price of "
                "broiler starter”, “who owes us”, “what's expiring”, “stock value”, “expenses this "
                "month”, “net profit this month”.")
    item = None
    if not stock.empty:
        words = set(_re.findall(r"[a-z0-9]+", ql))
        best = 0
        for _, r in stock.iterrows():
            nw = [w for w in _re.findall(r"[a-z0-9]+", r["name"].lower()) if len(w) > 2]
            score = sum(1 for w in nw if w in words)
            if r["name"].lower() in ql:
                score += 10
            if score > best and score >= max(1, min(2, len(nw))):
                best, item = score, r
    if has("expense", "spent", "spend", "spending", "costs"):
        s_, e_, lab_ = period()
        ef_ = expenses_frame(s_, e_)
        if ef_.empty:
            return f"No expenses recorded {lab_}."
        bc_ = ef_.groupby("category")["amount"].sum().sort_values(ascending=False)
        return (f"Expenses {lab_}: {money(ef_['amount'].sum())} across {len(ef_)} payment(s).\n"
                + "\n".join(f"• {k}: {money(v)}" for k, v in bc_.head(6).items()))
    if has("net profit"):
        s_, e_, lab_ = period()
        sf_ = sales_frame(s_, e_)
        gp_ = float(sf_["profit"].sum()) if not sf_.empty else 0.0
        ex_ = expenses_total(s_, e_)
        return (f"Net profit {lab_}: {money(gp_ - ex_)} (gross profit {money(gp_)} minus "
                f"expenses {money(ex_)}).")
    if has("owe", "debt", "debtor", "credit", "balance", "account"):
        b = customer_balances()
        b = b[b["balance"] > 0.004] if not b.empty else b
        if b.empty:
            return "No customer owes the store anything right now. 👍"
        b = b.sort_values("balance", ascending=False)
        lines = "\n".join(f"• {r['name']}: {money(r['balance'])}" for _, r in b.head(10).iterrows())
        return f"{len(b)} customer(s) owe a total of {money(b['balance'].sum())}:\n{lines}"
    if has("expir", "expire", "best before"):
        ex = expiring_batches(30)
        if ex.empty:
            return "Nothing on the shelf expires within 30 days."
        return "Expiring within 30 days:\n" + "\n".join(
            f"• {r['Product']} (batch {r['Batch']}, {fmt(r['On shelf'])} left) — {r['When']}"
            for _, r in ex.head(12).iterrows())
    if has("low", "reorder", "out of stock", "run out", "running out", "order more"):
        if stock.empty:
            return "No products yet."
        low = stock[stock["soh"] <= stock["reorder_level"]].sort_values("soh")
        if low.empty:
            return "Everything is above its reorder level. ✅"
        return f"{len(low)} product(s) need reordering:\n" + "\n".join(
            f"• {r['name']}: {fmt(r['soh'])} {r['sell_unit']} left (reorder at "
            f"{fmt(r['reorder_level'])})" for _, r in low.iterrows())
    if has("stock value", "worth", "valuation"):
        if stock.empty:
            return "No products yet."
        return (f"Stock on hand is worth {money(stock['stock_value'].sum())} at cost and "
                f"{money(stock['retail_value'].sum())} at selling price.")
    if item is not None and has("price", "cost", "how much is", "sell for"):
        return (f"{item['name']} sells for {money(item['sell_price'])} per {item['sell_unit']} "
                f"(cost {money(item['cost_price'])}, margin {item['margin_pct']:.0f}%).")
    if item is not None and not has("sales", "sold", "revenue", "profit"):
        return (f"{item['name']}: {fmt(item['soh'])} {item['sell_unit']} in stock — "
                f"{item['level']}. Sold {fmt(item['sold30'])} in the last 30 days; "
                f"price {money(item['sell_price'])}.")
    s, e, lab = period()
    sales = sales_frame(s, e)
    if has("best", "top", "most sold", "popular", "best seller", "bestseller"):
        it = items_frame(s, e)
        if it.empty:
            return f"No sales {lab}."
        g = it.groupby("name")["qty"].sum().sort_values(ascending=False)
        return f"Best sellers {lab}:\n" + "\n".join(
            f"• {n}: {fmt(v)}" for n, v in g.head(5).items())
    if item is not None:
        it = items_frame(s, e)
        it = it[it["product_id"] == item["id"]] if not it.empty else it
        if it.empty:
            return f"No {item['name']} sold {lab}."
        return (f"{item['name']}: {fmt(it['qty'].sum())} {item['sell_unit']} sold {lab}, "
                f"bringing in {money(it['line_total'].sum())}.")
    if has("profit", "margin", "made"):
        if sales.empty:
            return f"No sales {lab}."
        return (f"Gross profit {lab}: {money(sales['profit'].sum())} on sales of "
                f"{money(sales['net_ex_vat'].sum())} (ex VAT).")
    if has("sale", "sold", "revenue", "takings", "income", "how much did"):
        if sales.empty:
            return f"No sales {lab}."
        return (f"Sales {lab}: {money(sales['total'].sum())} from {len(sales)} sale(s). "
                f"Cash {money(sales.loc[sales['method'] == 'Cash', 'total'].sum())}, "
                f"on account {money((sales['total'] - sales['paid']).sum())}.")
    return ("I'm not sure about that one. Try “sales today”, “profit this month”, “best "
            "seller this week”, “what's low”, “who owes us” or a product name.")


