# ══════════════════════════════════════════════
# INSTALLATION PASSKEY / ACTIVATION
# Each computer must be activated once with the installation passkey. Only a salted hash of
# the passkey is kept here; activation is a token tied to this computer, stored next to the
# app (.hdm_pos_activation) and in the database.
# ══════════════════════════════════════════════
_ACT_SALT = b"hdm-pos-install-v1"
_ACT_HASHES = {"31799543376c8fa21fde60965fa188ec8cd119dbe41a0d77db4900dac87e2927",
               "852ffd7453f49f438c209ba8f7bde0664637a19bf0ea2200e102729e72ca914b"}
_ACT_FILE = (os.environ.get("SALES_ACTIVATION_PATH")
             or os.path.join(os.path.dirname(os.path.abspath(globals().get("__file__", "app.py"))),
                             ".hdm_pos_activation"))


def _passkey_ok(key):
    h = _hashlib.pbkdf2_hmac("sha256", (key or "").strip().encode("utf-8"), _ACT_SALT, 200_000)
    return h.hex() in _ACT_HASHES


def _machine_fingerprint():
    node = _uuid.getnode()
    mac = "" if (node >> 40) & 1 else f"{node:012x}"   # ignore a random (non-hardware) id
    return f"{mac}|{_platform.node()}|{_platform.system()}"


def _activation_token():
    return _hashlib.sha256(_ACT_SALT + b"|activated|"
                           + _machine_fingerprint().encode("utf-8")).hexdigest()


def is_activated():
    tok = _activation_token()
    try:
        with open(_ACT_FILE, encoding="utf-8") as fh:
            if fh.read().strip() == tok:
                return True
    except Exception:
        pass
    return get_setting("activation_token", "") == tok


def activate_this_computer():
    tok = _activation_token()
    try:
        with open(_ACT_FILE, "w", encoding="utf-8") as fh:
            fh.write(tok)
    except Exception:
        pass                      # read-only folder: the database copy is enough
    set_setting("activation_token", tok)
    set_setting("activated_at", stamp())
    set_setting("activated_on", _platform.node())


def activation_gate():
    """Full-screen activation form until this computer is activated."""
    if is_activated():
        return
    s_ = st.session_state
    s_.setdefault("act_fails", 0)
    s_.setdefault("act_lock_until", None)
    st.markdown("""<style>[data-testid="stSidebar"], [data-testid="collapsedControl"],
        [data-testid="stSidebarCollapsedControl"], .st-key-chat_toggle { display:none !important; }
        </style>""", unsafe_allow_html=True)
    _, mid, _ = st.columns([1, 1.4, 1])
    with mid:
        st.markdown(f'<div style="text-align:center;margin-top:6vh;">'
                    f'{system_icon_img(88, "border-radius:20px;")}'
                    f'<div style="font-size:1.7rem;font-weight:800;color:#2B4F8E;margin-top:12px;">'
                    f'Activate Sales Manager</div>'
                    f'<div style="color:{MUTED};margin:.3rem 0 1.2rem 0;">Enter the installation '
                    f'passkey to use HDM POS on this computer. You only need to do this once.'
                    f'</div></div>', unsafe_allow_html=True)
        locked = (s_["act_lock_until"] is not None and now_local() < s_["act_lock_until"])
        with st.form("activate"):
            key_in = st.text_input("Installation passkey", type="password", key="act_key")
            go_ = st.form_submit_button("Activate", type="primary", use_container_width=True,
                                        disabled=locked)
        if locked:
            wait = int((s_["act_lock_until"] - now_local()).total_seconds()) + 1
            st.error(f"Too many wrong attempts. Try again in {wait} seconds.")
        elif go_:
            if _passkey_ok(key_in):
                activate_this_computer()
                s_["act_fails"] = 0
                s_["_flash"] = "Sales Manager is activated on this computer. Welcome!"
                st.rerun()
            else:
                s_["act_fails"] += 1
                if s_["act_fails"] >= 5:
                    s_["act_lock_until"] = now_local() + timedelta(seconds=60)
                    s_["act_fails"] = 0
                    st.error("Too many wrong attempts. Try again in 60 seconds.")
                else:
                    st.error(f"That passkey isn't right. {5 - s_['act_fails']} attempt(s) left "
                             f"before a short lock.")
        st.caption("Don't have the passkey? Contact Health Data Matrics.")
    st.stop()


