if page == "Dashboard":
    t = today_local()
    _hr = now_local().hour
    _greet = "Good morning" if _hr < 12 else ("Good afternoon" if _hr < 17 else "Good evening")
    st.markdown(f'<div class="hello">{_greet}{", " + _esc(cashier_name()) if cashier_name() else ""}'
                f'</div><div class="hello-sub">{_esc(store_name())} · {t:%A, %d %B %Y}</div>',
                unsafe_allow_html=True)
    qa1, qa2, qa3, qa4 = st.columns(4)
    if qa1.button("New sale", type="primary", use_container_width=True, key="qa_sale"):
        go_to("Point of sale")
    if qa2.button("Sell on credit", use_container_width=True, key="qa_credit"):
        go_to("Customers", "tabs_customers", "sell")
    if qa3.button("Record expense", use_container_width=True, key="qa_exp"):
        go_to("Expenses", "tabs_expenses", "record")
    if qa4.button("Receive stock", use_container_width=True, key="qa_recv"):
        go_to("Receive stock")

    _tab = tab_bar("tabs_dashboard", [
        ("sales", "Sales overview", "Today's takings and profit, the 30-day trend, best sellers, "
                                    "stock alerts and money owed."),
        ("expenses", "Expenses", "What the store spends, how it compares with sales, and the "
                                 "net profit left over."),
    ])
    stock = _sb_stock

    if _tab == "sales":
        if stock.empty:
            st.info("Welcome! Start by adding your feeds under **Products & stock** (or import a "
                    "price list), then ring up sales under **Point of sale**.")
            if st.button("➕ Add products", type="primary"):
                go_to("Products & stock", "tabs_products", "add")
        else:
            today_s = sales_frame(t, t)
            yest_s = sales_frame(t - timedelta(days=1), t - timedelta(days=1))
            month_s = sales_frame(t.replace(day=1), t)
            _lm0 = month_start(t, 1)
            lm_s = sales_frame(_lm0, min(_lm0 + timedelta(days=t.day - 1), month_end(_lm0)))

            def tot(d, c="total"):
                return float(d[c].sum()) if not d.empty else 0.0
            bal = customer_balances()
            owed = float(bal.loc[bal["balance"] > 0, "balance"].sum()) if not bal.empty else 0.0
            n_owing = int((bal["balance"] > 0.004).sum()) if not bal.empty else 0
            low = stock[stock["soh"] <= stock["reorder_level"]].sort_values("soh")
            p_today = change_pill(tot(today_s), tot(yest_s))
            p_month = change_pill(tot(month_s), tot(lm_s), vs="vs last month")
            kpi_row([
                ("💰", "Sales today", money(tot(today_s)), PRIMARY) + p_today,
                ("🧾", "Transactions today", len(today_s), ACCENT,
                 f"avg {money(tot(today_s) / len(today_s))}" if len(today_s) else "none yet"),
                ("📈", "Gross profit today", money(tot(today_s, "profit")), OK_GREEN,
                 "after cost of feed, ex VAT"),
                ("🗓️", "Sales this month", money(tot(month_s)), GOLD) + p_month,
                ("📒", "Owed by customers", money(owed), DANGER if owed > 0 else OK_GREEN,
                 f"{n_owing} customer{'s' if n_owing != 1 else ''}" if n_owing else "all paid up"),
                ("⚠️", "Products to reorder", len(low), WARN if len(low) else OK_GREEN,
                 "at or below reorder level" if len(low) else "stock healthy"),
            ])

            s30 = sales_frame(t - timedelta(days=29), t)
            c1, c2 = st.columns([2, 1])
            with c1:
                with card():
                    idx = [(t - timedelta(days=i)).isoformat() for i in range(29, -1, -1)]
                    daily = (s30.groupby("day")["total"].sum() if not s30.empty
                             else pd.Series(dtype=float)).reindex(idx, fill_value=0.0)
                    card_head("Sales — last 30 days",
                              f"{money(daily.sum())} in total · best day {money(daily.max())}")
                    st.plotly_chart(trend_fig(pd.to_datetime(daily.index), daily.values,
                                              daily.rolling(7, min_periods=1).mean().values),
                                    use_container_width=True, config={"displayModeBar": False})
            with c2:
                with card():
                    card_head("How customers pay", "last 30 days")
                    if s30.empty:
                        st.caption("No sales yet.")
                    else:
                        pm = s30.groupby("method")["total"].sum().sort_values(ascending=False)
                        pm.index = [("On credit" if m == ACCOUNT_METHOD else m) for m in pm.index]
                        st.plotly_chart(donut_fig(pm.index, pm.values,
                                                  center=f"<b>{len(s30)}</b><br>sales"),
                                        use_container_width=True,
                                        config={"displayModeBar": False})

            c3, c4 = st.columns(2)
            with c3:
                with card():
                    card_head("Best sellers", "by takings, last 30 days")
                    it = items_frame(t - timedelta(days=29), t)
                    if it.empty:
                        st.caption("No sales yet.")
                    else:
                        top = (it.groupby("name").agg(rev=("line_total", "sum"),
                                                      qty=("qty", "sum"))
                               .sort_values("rev", ascending=False).head(6))
                        mx = float(top["rev"].max()) or 1.0
                        bars_html([(n, money(r["rev"]), r["rev"] / mx, f"{fmt(r['qty'])} sold")
                                   for n, r in top.iterrows()], color=PRIMARY)
            with c4:
                with card():
                    card_head("Stock alerts", "products at or below their reorder level")
                    if low.empty:
                        st.success("Every product is above its reorder level.")
                    else:
                        rows_ = []
                        for _, r in low.head(6).iterrows():
                            target = max(float(r["reorder_level"]) * 2, 1.0)
                            dl_ = r["days_left"]
                            note = (("Out of stock" + (f" — oversold by {fmt(-r['soh'])}"
                                                       if r["soh"] < 0 else ""))
                                    if r["soh"] <= 0 else
                                    f"reorder at {fmt(r['reorder_level'])}"
                                    + (f" · about {dl_:.0f} days left"
                                       if dl_ is not None and not pd.isna(dl_) else ""))
                            rows_.append((r["name"], f"{fmt(r['soh'])} {r['sell_unit']}",
                                          max(float(r["soh"]), 0) / target, note))
                        bars_html(rows_, color=DANGER)
                        if len(low) > 6:
                            st.caption(f"+ {len(low) - 6} more — see Products & stock.")
                        if st.button("Restock a product", key="dash_restock"):
                            go_to("Products & stock", "tabs_products", "restock")

            c5, c6 = st.columns(2)
            with c5:
                with card():
                    card_head("Expiring soon", "batches on the shelf expiring within 30 days")
                    ex = expiring_batches(30)
                    if ex.empty:
                        st.success("Nothing on the shelf expires in the next 30 days.")
                    else:
                        st.dataframe(ex[["Product", "Batch", "Expiry", "On shelf", "When"]].assign(
                            **{"On shelf": ex["On shelf"].map(fmt)}),
                            use_container_width=True, hide_index=True)
            with c6:
                with card():
                    card_head("Who owes the store", "biggest customer balances")
                    debt = (bal[bal["balance"] > 0.004].sort_values("balance", ascending=False)
                            if not bal.empty else bal)
                    if debt.empty:
                        st.success("No customer owes the store anything.")
                    else:
                        mx = float(debt["balance"].max()) or 1.0
                        bars_html([(r["name"], money(r["balance"]), r["balance"] / mx,
                                    f"last payment {r['last_payment']}"
                                    if r["last_payment"] not in ("—", "", None)
                                    else "no payments yet")
                                   for _, r in debt.head(6).iterrows()], color=GOLD)
                        if st.button("Record a payment", key="dash_pay"):
                            go_to("Customers", "tabs_customers", "pay")

    if _tab == "expenses":
        m0, m1 = t.replace(day=1), t
        lm0 = month_start(t, 1)
        lm1 = min(lm0 + timedelta(days=t.day - 1), month_end(lm0))
        exp_m, exp_lm = expenses_total(m0, m1), expenses_total(lm0, lm1)
        exp_today = expenses_total(t, t)
        ms = sales_frame(m0, m1)
        gross = float(ms["profit"].sum()) if not ms.empty else 0.0
        rev_ex = float(ms["net_ex_vat"].sum()) if not ms.empty else 0.0
        net = gross - exp_m
        pill = change_pill(exp_m, exp_lm, rising_is_good=False, vs="vs last month")
        kpi_row([
            ("💸", "Expenses this month", money(exp_m), DANGER) + pill,
            ("🧾", "Expenses today", money(exp_today), WARN),
            ("📈", "Gross profit this month", money(gross), OK_GREEN, "sales minus cost of feed"),
            ("✅", "Net profit this month", money(net), OK_GREEN if net >= 0 else DANGER,
             "gross profit minus expenses"),
            ("📊", "Expenses vs sales", f"{(100 * exp_m / rev_ex) if rev_ex else 0:.0f}%", GOLD,
             "of sales (ex VAT) this month"),
        ])
        b1, _ = st.columns([1, 3])
        if b1.button("Record an expense", type="primary", key="dash_add_exp",
                     use_container_width=True):
            go_to("Expenses", "tabs_expenses", "record")

        em = expenses_frame(m0, m1)
        bc = (em.groupby("category")["amount"].sum().sort_values(ascending=False)
              if not em.empty else pd.Series(dtype=float))
        c1, c2 = st.columns([2, 1])
        with c1:
            with card():
                card_head("Sales, expenses and net profit", "last 6 months")
                lab_, sal_, exp_, net_ = [], [], [], []
                for k in range(5, -1, -1):
                    m = month_start(t, k)
                    me = min(month_end(m), t)
                    sf = sales_frame(m, me)
                    gp = float(sf["profit"].sum()) if not sf.empty else 0.0
                    ev = expenses_total(m, me)
                    lab_.append(f"{m:%b %Y}")
                    sal_.append(float(sf["net_ex_vat"].sum()) if not sf.empty else 0.0)
                    exp_.append(ev)
                    net_.append(gp - ev)
                fig = go.Figure()
                fig.add_trace(go.Bar(x=lab_, y=sal_, name="Sales (ex VAT)", marker_color=ACCENT,
                                     hovertemplate="%{x}<br>Sales " + currency()
                                     + " %{y:,.2f}<extra></extra>"))
                fig.add_trace(go.Bar(x=lab_, y=exp_, name="Expenses", marker_color="#D9826F",
                                     hovertemplate="%{x}<br>Expenses " + currency()
                                     + " %{y:,.2f}<extra></extra>"))
                fig.add_trace(go.Scatter(x=lab_, y=net_, name="Net profit", mode="lines+markers",
                                         line=dict(color=PRIMARY, width=2.5),
                                         marker=dict(size=7),
                                         hovertemplate="%{x}<br>Net profit " + currency()
                                         + " %{y:,.2f}<extra></extra>"))
                fig = _fig_layout(fig, 320, legend=True)
                fig.update_layout(barmode="group", bargap=0.35)
                st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": False})
        with c2:
            with card():
                card_head("Where the money goes", f"{t:%B} by category")
                if bc.empty:
                    st.caption("No expenses recorded this month.")
                else:
                    st.plotly_chart(donut_fig(bc.index, bc.values,
                                              center=f"<b>{money(bc.sum())}</b>"),
                                    use_container_width=True, config={"displayModeBar": False})

        c3, c4 = st.columns(2)
        with c3:
            with card():
                card_head("Biggest costs", f"{t:%B} so far")
                if bc.empty:
                    st.caption("No expenses recorded this month.")
                else:
                    mx = float(bc.max()) or 1.0
                    bars_html([(cat_, money(v_), v_ / mx,
                                f"{100 * v_ / bc.sum():.0f}% of spending")
                               for cat_, v_ in bc.head(6).items()], color="#D9826F")
        with c4:
            with card():
                card_head("Recent expenses")
                rec = expenses_frame().head(8)
                if rec.empty:
                    st.caption("No expenses recorded yet.")
                else:
                    st.dataframe(pd.DataFrame({
                        "Date": rec["exp_date"], "Category": rec["category"],
                        "Description": rec["description"], "Amount": rec["amount"].map(money),
                        "Paid by": rec["method"]}), use_container_width=True, hide_index=True)


