            sku = b4.text_input("SKU / barcode")
            c1, c2, c3, c4 = st.columns(4)
            cost = c1.number_input(f"Cost price ({currency()}, excl. VAT)", min_value=0.0,
                                   step=5.0)
            price = c2.number_input(f"Selling price ({currency()}, as on the shelf)",
                                    min_value=0.0, step=5.0)
