    if _tab == "import":
        st.caption("Load your whole price list at once. Column names are matched loosely "
                   "(e.g. 'Item', 'Selling price', 'Qty', 'Cost'). Only a name is required. "
                   "Existing products (same name) get their prices updated; opening stock is "
                   "only added for new products.")
        tpl = ("name,category,brand,sell unit,pack size,cost price,selling price,opening stock,"
               "reorder at,sku\n"
               "Layer Mash 50kg,Poultry feed,Sebele,bag,50,395,450,40,10,LM50\n"
               "Broiler Starter 50kg,Poultry feed,Sebele,bag,50,420,485,30,8,BS50\n"
               "Dairy Meal 50kg,Cattle feed,Feedmaster,bag,50,330,380,25,6,DM50\n"
               "Pig Grower 40kg,Pig feed,Feedmaster,bag,40,310,360,20,5,PG40\n"
               "Game & Cattle Lick 40kg,Licks & supplements,Voermol,bag,40,260,305,15,5,GL40\n"
               "Dog Food 20kg,Dog & cat food,Bobtail,bag,20,280,330,12,4,DF20\n")
        save_download("⬇️ Download template (CSV)", tpl, "feed-price-list-template.csv",
                      "text/csv", key="tpl")
        up = st.file_uploader("CSV or Excel file", type=["csv", "xlsx"], key="imp")
        if up is not None:
            try:
                if up.name.lower().endswith(".csv"):
                    try:
                        raw = pd.read_csv(up, encoding="utf-8-sig")
                    except UnicodeDecodeError:
                        up.seek(0)
                        raw = pd.read_csv(up, encoding="latin-1")
                else:
                    raw = pd.read_excel(up, engine="openpyxl")
            except Exception as ex_:
                raw = None
                st.error(f"Couldn't read that file: {ex_}")
            if raw is not None:
                def norm(s):
                    return _re.sub(r"[^a-z0-9]+", " ", str(s).lower()).strip()
                rules = [("cost", ["cost", "buying", "purchase price", "landed"]),
                         ("price", ["selling", "sell price", "retail", "price", "rsp"]),
                         ("opening", ["opening", "qty", "quantity", "stock", "on hand", "count"]),
                         ("reorder", ["reorder", "minimum", "min level", "alert"]),
                         ("pack", ["pack", "size", "weight", "kg"]),
                         ("unit", ["unit", "uom", "sold per", "sell unit"]),
                         ("category", ["categor", "type", "group", "animal"]),
                         ("brand", ["brand", "make", "manufacturer"]),
                         ("sku", ["sku", "code", "barcode"]),
                         ("name", ["name", "item", "product", "description", "feed"])]
                cmap, used = {}, set()
                for field, keys in rules:
                    for col in raw.columns:
                        if col in used:
                            continue
                        if any(k in norm(col) for k in keys):
                            cmap[field] = col
                            used.add(col)
                            break
                if "name" not in cmap:
                    st.error("No product-name column found (call it 'name', 'item' or 'product').")
                else:
                    st.caption("Column mapping: " + " · ".join(f"{k} ← “{v}”" for k, v in cmap.items()))
                    st.dataframe(raw.head(8), use_container_width=True, hide_index=True)

                    def num(v, d=0.0):
                        try:
                            s_ = str(v).replace(",", "").replace(currency(), "").strip()
                            return float(s_) if s_ and s_.lower() != "nan" else d
                        except ValueError:
                            return d
                    if st.button(f"Import {len(raw)} row(s)", type="primary", key="imp_go"):
                        added = updated = 0
                        for _, rr in raw.iterrows():
                            nm_ = str(rr[cmap["name"]]).strip()
                            if not nm_ or nm_.lower() == "nan":
                                continue
                            g = lambda f, d="": rr[cmap[f]] if f in cmap and not pd.isna(rr[cmap[f]]) else d
                            ex_row = q("SELECT id FROM products WHERE lower(name)=lower(?)", (nm_,))
                            if ex_row.empty:
                                add_product(nm_, str(g("category", "")), str(g("brand", "")),
                                            num(g("pack", 0)), str(g("unit", "bag")) or "bag",
                                            str(g("sku", "")), num(g("cost", 0)),
                                            num(g("price", 0)), num(g("reorder", 5), 5),
                                            num(g("opening", 0)))
                                added += 1
                            else:
                                upd = {}
                                for f, col in (("cost", "cost_price"), ("price", "sell_price"),
                                               ("reorder", "reorder_level"), ("pack", "pack_size")):
                                    if f in cmap and str(g(f, "")).strip():
                                        upd[col] = num(g(f))
                                for f in ("category", "brand", "sku"):
                                    if f in cmap and str(g(f, "")).strip():
                                        upd[f] = str(g(f))
                                update_product(int(ex_row.iloc[0, 0]), **upd)
                                updated += 1
                        ss["_flash"] = f"Import done — {added} added, {updated} updated."
                        st.rerun()


